import { readFile } from 'node:fs/promises';
import type { TemporaryFile, SceneGenerator, SceneRequest } from '@pod/core';
import { mayHaveActed, sleep, type JsonObject } from '@pod/adapter-http';
import {
  GEMINI,
  GeminiError,
  GeminiNotConnectedError,
  GeminiSceneUnfinishedError,
  GeminiUnreadableAnswerError,
} from './errors.js';
import type { GeminiAccess } from './gemini-models.js';
import { geminiRequest, isTransient } from './gemini-api.js';

export interface GeminiSceneOptions extends GeminiAccess {
  /** Stores generated bytes in a temporary file the caller disposes of. */
  readonly writeTemporary: (bytes: Uint8Array, mimeType: string) => Promise<TemporaryFile>;
  readonly now?: () => number;
}

const POLL_MS = 2_000;
const TIMEOUT_MS = 180_000;
/** Polls that may fail in a row before the scene is given up. */
const POLL_ATTEMPTS = 3;

/** What a scene is asked for as, and taken to be when Gemini does not say. */
const SCENE_TYPE = 'image/jpeg';

/** Generates scenes with Gemini's Interactions API, sending the product photo inline. */
export class GeminiSceneGenerator implements SceneGenerator {
  private readonly fetchFn: typeof fetch;
  private readonly sleep: (milliseconds: number) => Promise<void>;
  private readonly now: () => number;

  constructor(private readonly options: GeminiSceneOptions) {
    this.fetchFn = options.fetch ?? fetch;
    this.sleep = options.sleep ?? sleep;
    this.now = options.now ?? Date.now;
  }

  async generate(request: SceneRequest): Promise<TemporaryFile> {
    const apiKey = await this.options.apiKey();
    if (!apiKey) throw new GeminiNotConnectedError();
    const photo = await readFile(request.image.absolutePath);
    let interaction = await this.start(apiKey, request, photo.toString('base64'));
    const deadline = this.now() + TIMEOUT_MS;
    const id = interaction['id'];
    while (interaction['status'] === 'in_progress') {
      if (typeof id !== 'string' || !id) {
        throw new GeminiSceneUnfinishedError('no readable answer');
      }
      if (this.now() >= deadline) {
        await this.cancel(apiKey, id);
        throw new GeminiSceneUnfinishedError();
      }
      await this.sleep(POLL_MS);
      interaction = await this.poll(apiKey, id);
    }
    if (interaction['status'] !== 'completed') throw new GeminiError(failureOf(interaction));
    // One scene was asked for; when the model shows drafts on the way, the last image is the finished one.
    const image = imagesOf(interaction).at(-1);
    if (!image) {
      // Gemini sometimes explains in text why it drew nothing, e.g. a refused prompt.
      const said = textOf(interaction);
      throw new GeminiError(`${GEMINI} answered without an image${said ? `: ${said}` : ''}`);
    }
    return this.options.writeTemporary(Buffer.from(image.data, 'base64'), image.mimeType);
  }

  /** Starts the scene; an answer that cannot be read leaves its outcome unknown. */
  private async start(apiKey: string, request: SceneRequest, photo: string): Promise<JsonObject> {
    const model = await this.options.model();
    try {
      return await geminiRequest(this.fetchFn, apiKey, '/interactions', {
        model,
        // The photo comes first, so the instructions are read with the product in view.
        input: [
          { type: 'image', mime_type: request.image.mimeType, data: photo },
          { type: 'text', text: request.prompt },
        ],
        // Etsy wants 2000 pixels or more; 4K stays sharp when buyers zoom in, in every shape.
        // JPEG keeps such a photo a few megabytes, where PNG would be tens.
        response_format: {
          type: 'image',
          mime_type: SCENE_TYPE,
          aspect_ratio: request.shape,
          image_size: '4K',
        },
        // Runs on Google's side and is polled, so a slow scene does not hold one long request open.
        background: true,
      });
    } catch (error) {
      if (error instanceof GeminiUnreadableAnswerError) {
        throw new GeminiSceneUnfinishedError('no readable answer', error);
      }
      // A fault on Google's side may come after the scene was started.
      if (mayHaveActed(error, GeminiError))
        throw new GeminiSceneUnfinishedError('no answer', error);
      throw error;
    }
  }

  /**
   * Asks Google to stop a scene given up on, so it is not finished for nothing;
   * when that fails, the scene may still be made and billed.
   */
  private async cancel(apiKey: string, id: string): Promise<void> {
    await geminiRequest(
      this.fetchFn,
      apiKey,
      `/interactions/${encodeURIComponent(id)}/cancel`,
      {},
    ).catch(() => undefined);
  }

  /**
   * Asks again after a network error, a rate limit or a fault on Google's side,
   * which a moment often cures. When the tries run out, the scene's outcome is
   * unknown, and it may already be billed.
   */
  private async poll(apiKey: string, id: string): Promise<JsonObject> {
    for (let attempt = 1; ; attempt += 1) {
      try {
        return await geminiRequest(this.fetchFn, apiKey, `/interactions/${encodeURIComponent(id)}`);
      } catch (error) {
        if (error instanceof GeminiUnreadableAnswerError) {
          throw new GeminiSceneUnfinishedError('no readable answer', error);
        }
        const passing = !(error instanceof GeminiError) || isTransient(error.status);
        if (!passing) throw error;
        if (attempt >= POLL_ATTEMPTS) throw new GeminiSceneUnfinishedError('no answer', error);
        await this.sleep(POLL_MS);
      }
    }
  }
}

function failureOf(interaction: JsonObject): string {
  const errors = Array.isArray(interaction['errors'])
    ? (interaction['errors'] as JsonObject[])
    : [];
  const message = errors.find((error) => typeof error['message'] === 'string')?.['message'];
  const status = typeof interaction['status'] === 'string' ? interaction['status'] : 'unknown';
  return `${GEMINI} ${status === 'failed' ? 'failed' : `stopped (${status})`}: ${
    typeof message === 'string' ? message : 'no reason given'
  }`;
}

/** What the model wrote in its output steps, shortened for an error message. */
function textOf(interaction: JsonObject): string {
  const text = outputsOf(interaction)
    .flatMap((content) =>
      content['type'] === 'text' && typeof content['text'] === 'string' ? [content['text']] : [],
    )
    .join(' ')
    .trim();
  return text.length > 300 ? `${text.slice(0, 300)}…` : text;
}

function outputsOf(interaction: JsonObject): JsonObject[] {
  const steps = Array.isArray(interaction['steps']) ? (interaction['steps'] as JsonObject[]) : [];
  return steps
    .filter((step) => step['type'] === 'model_output' && Array.isArray(step['content']))
    .flatMap((step) => step['content'] as JsonObject[]);
}

/** Images in the model's output steps, as base64 with their type. */
function imagesOf(interaction: JsonObject): { data: string; mimeType: string }[] {
  return outputsOf(interaction).flatMap((content) =>
    content['type'] === 'image' && typeof content['data'] === 'string'
      ? [
          {
            data: content['data'],
            mimeType: typeof content['mime_type'] === 'string' ? content['mime_type'] : SCENE_TYPE,
          },
        ]
      : [],
  );
}
